                        manifest_json=to_text(_MANIFEST_JSON),
                        galaxy_yml=to_text(_GALAXY_YAML),
                    )
                )
            req_type = 'dir'
            req_source = src_path
        elif _is_collection_namespace_dir(src_path):
            req_name = None  # No name for a virtual req or "namespace."?
            req_type = 'subdirs'
